import {generateSeed} from './engine/probability.js';
import {createPlayer} from './state/player.js';
import {loadSave,saveGame,emptySave,updateSave,settings,setSettings} from './state/storage.js';
import {advanceYear,choose,rewind} from './engine/year.js';
import {applyEffects} from './engine/effect.js';
import {netWorth,totalDebt,home} from './engine/finance.js';
import {getReport,aspirationProgress,titles} from './engine/report.js';
import {cities,cityById} from './data/cities.js';
import {careerById} from './data/careers.js';
import {labels,hobbyNames,educationNames,money,number} from './data/catalog.js';
const root=document.querySelector('#app');const debug=new URLSearchParams(location.search).get('debug')==='1';
let save=emptySave(),view='home',tab='year',busy=false,error='',saved=true,ready=false,archive=null,prefs=settings(),autoAdvanceTimer=null,yearFeedScrollTimer=null,yearTransitionFromAge=null;
const AUTO_ADVANCE_DELAY=1200;
const esc=v=>String(v??'暂无').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,action,cls='',disabled=false,extra='')=>`<button class="${cls}" data-action="${action}" ${disabled||busy?'disabled':''} ${extra}>${esc(text)}</button>`;
const row=(k,v)=>`<div class="row"><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`;
const card=(title,content)=>`<section class="page-card"><h2 class="section-title">${esc(title)}</h2>${content}</section>`;
const job=s=>s.retired?'已退休':careerById(s.career)?.name??(s.age<18||s.age<22&&s.education===5?'学生':'待业');
const tabs=[['year','这一年'],['person','人物'],['hobbies','爱好'],['relations','关系'],['family','家庭'],['career','职业'],['wealth','财富'],['cities','城市足迹'],['history','人生履历']];
function header(){return `<header class="topbar"><div class="brand">人生手记<span class="edition">中国城市人生模拟</span></div><div class="top-actions">${button('首页','home','quiet')}${button('设置','settings','quiet')}</div></header>`;}
function homePage(){return `<section class="intro"><div class="eyebrow">${cities.length}座城市，无数种人生</div><h1>从这里，过一生。</h1><p>出生时的家乡，后来遇见的人，喜欢过的事。<br>有些路由你选择，有些事在多年以后才有回声。</p><div class="home-actions">${button('开始新人生','create','primary',!ready)}${button('继续人生','continue','',!save.current)}${button('历史人生','past')}</div>${save.current?`<p class="footnote">上次停在：${esc(save.current.name)} · ${save.current.age}岁 · ${cityById(save.current.city).name}${save.current.dead?' · 已走完这一生':''}</p>`:''}</section>`;}
function createPage(){return `<section class="new-life"><div class="eyebrow">人生的第一页</div><h2>你将从哪里出发？</h2><p class="footnote">家庭、天赋和先天兴趣随出生生成。之后的生活，由经历慢慢改变。</p>${save.current&&!save.current.dead?'<p class="notice">开始新人生会替换当前进度。已经结束的人生仍保留。</p>':''}<form id="create-form"><div class="form-row section-title"><div class="field"><label for="name">姓名（留空随机）</label><input id="name" name="name" maxlength="12" placeholder="让命运取个名字" autocomplete="off"></div><div class="field"><label for="gender">性别</label><select id="gender" name="gender"><option>随机</option><option>男</option><option>女</option></select></div></div><div class="field"><label for="city">出生城市</label><select id="city" name="city"><option value="random">随机城市</option>${cities.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div><p class="city-note" id="city-note">出生地只是起点，你可以在重大人生节点迁居。</p>${debug?'<div class="field"><label for="seed">开发复现种子</label><input id="seed" name="seed" placeholder="留空生成新的种子"></div>':''}<button type="submit" class="primary" ${busy?'disabled':''}>开始人生</button></form></section>`;}
function stats(s){return `<div class="stats">${[['健康',number(s.stats.health)],['快乐',number(s.stats.happiness)],['现金',money(s.cash)],['总资产（净值）',money(netWorth(s))]].map(([k,v])=>`<div class="metric"><label>${k}</label><strong class="${String(v).startsWith('-')?'negative':''}">${v}</strong></div>`).join('')}</div>`;}
function financeDetails(f){return f?`<details><summary>查看年度收支</summary><dl class="balance">${[['年度收入',f.income],['生活成本',-f.living],['房租',-f.rent],['家庭支出',-f.family],['房贷还款',-f.mortgage],['其他债务利息',-f.debtInterest],['投资账面变化',f.investmentChange],['基础现金变化',f.change]].map(([k,v])=>row(k,money(v))).join('')}</dl><p class="footnote">此处为年度基础结算，事件带来的收支另计。投资变化计入资产，不重复计入现金。</p></details>`:'';}
function canRewindAt(s,e){return !!(e?.key&&!s.rewindUsed&&save.checkpoint&&e.age===save.checkpoint.age);}
function yearSlide(s,e,{pending=false,current=false}={}){const age=pending?s.age:e.age,year=pending?s.birthYear+s.age:e.year,city=pending?s.city:e.city,notes=pending?s.frame?.notes:e.background;const badge=pending?'人生岔路':age===0?'故事开始':e.key?'人生选择':'这一年的记忆';const rewindButton=!pending&&canRewindAt(s,e)?button('时光倒流 · 一次','rewind','quiet'):'';return `<section class="year-slide${current?' current':''}" data-age="${age}" ${current?'data-current-year="true"':''}><article class="page-card"><div class="yearline"><span>${year}年 · ${age}岁 · ${cityById(city).name}</span><b>${badge}</b></div><h2>${esc(e.title)}</h2><p class="story">${esc(e.text)}</p>${e.choice?`<p class="choice-taken">你的选择：${esc(e.choice)}</p>`:''}${notes?.length?`<div class="background">${notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`:''}${pending?`<p class="muted">你决定：</p><div class="choices">${e.options.map((o,i)=>button(o.text,'choose','','',`data-index="${i}"`)).join('')}</div>`:''}${financeDetails(pending?s.frame?.finance:e.finance)}${rewindButton?`<div class="next-bar">${rewindButton}</div>`:''}<p class="footnote">${pending?'关键选择会暂停自动推进。做出决定后，人生继续向前。':current?'普通年份会自动进入下一年；向上滑可以回看过去。':'上下滑动，翻阅这一段人生。'}</p></article></section>`;}
function yearPage(s){const lastIndex=s.history.length-1;const history=s.history.map((e,i)=>yearSlide(s,e,{current:!s.pending&&i===lastIndex})).join('');const pending=s.pending?yearSlide(s,s.pending,{pending:true,current:true}):'';return `<section class="year-feed" aria-label="逐年人生经历">${history}${pending}</section>`;}
function personPage(s){return card('人物',`<dl>${row('姓名',s.name)}${row('性别',s.gender)}${row('出生年份',s.birthYear+'年')}${row('家乡',cityById(s.birthCity).name)}${Object.entries(s.stats).map(([k,v])=>row(labels[k],number(v))).join('')}${row('人格倾向',Object.entries(s.personality).filter(([,v])=>v>=10).map(([k])=>labels[k]).join('、')||'尚未形成明显倾向')}${row('人生愿望',s.aspiration)}${row('完成度',aspirationProgress(s)+'%')}${row('长期标签',s.tags.join('、')||'暂无')}</dl><p class="footnote">属性可以低于零，也可以超过一百。一百不是满值。</p><details><summary>最近的属性变化</summary><dl>${s.audit.filter(a=>a.effect.type==='stat').slice(-15).reverse().map(a=>row(a.age+'岁 · '+labels[a.effect.key],`${a.before} → ${a.after}\n${a.source}`)).join('')||'<p class="footnote">目前是出生时的初始属性。</p>'}</dl></details>${debug?button('导出开发日志','debug','quiet'):''}`);}
function hobbiesPage(s){return card('喜欢过的事',`<p class="footnote">先天兴趣与天赋相互独立。现在的兴趣会随环境、社团、朋友和经历改变。</p><dl>${hobbyNames.map(h=>row(h,`${number(s.hobbies[h])} · 先天兴趣 ${s.innateHobbies[h]}`)).join('')}</dl><h3 class="section-title">先天天赋</h3><dl>${['gaming','sport','music','acting'].map(k=>row(labels[k],number(s.hidden[k]))).join('')}</dl>`);}
function relationsPage(s){return card('那些相遇的人',s.npcs.length?s.npcs.map(n=>`<section class="history-item"><h3>${esc(n.name)} <small>${esc(n.role)}</small></h3><dl>${row('近况',n.age+'岁 · '+cityById(n.city).name+' · '+(n.alive?'健在':'已故'))}${row('职业',careerById(n.career)?.name??'尚未从业')}${row('性格',n.personality)}${row('关系 / 信任',number(n.relationship)+' / '+number(n.trust))}${row('共同经历',n.experiences.slice(-4).map(x=>x.age+'岁 · '+x.text).join('；'))}</dl></section>`).join(''):'<p class="empty">重要的人会在成长中慢慢出现。</p>');}
function familyPage(s){return card('家人',`<h3 class="section-title">父母</h3>${s.parents.map(p=>`<section class="history-item"><h3>${p.role} · ${esc(p.name)}</h3><dl>${row('近况',p.age+'岁 · '+(p.alive?'健在':'已故')+' · '+cityById(p.city).name)}${row('职业',p.retired?'已退休':careerById(p.career)?.name??'暂无')}${row('行业 / 单位',p.industry+' / '+p.unit)}${row('学历 / 性格',educationNames[p.education]+' / '+p.personality)}${row('年收入',money(p.income))}${row('健康 / 关系',number(p.health)+' / '+p.relationship)}${row('爱好',p.hobby)}</dl></section>`).join('')}<h3 class="section-title">自己的家庭</h3><dl>${row('感情',s.relationshipStatus)}${s.partner?row('伴侣',s.partner.name+' · '+s.partner.age+'岁 · '+cityById(s.partner.city).name)+row('职业 / 收入',(careerById(s.partner.career)?.name??'暂无')+' / '+money(s.partner.income))+row('性格 / 关系',s.partner.personality+' / '+s.partner.relationship):row('伴侣','暂未遇见')}${row('子女',s.children.map(c=>c.name+' · '+c.age+'岁').join('；')||'暂无子女')}</dl>`);}
function careerPage(s){const c=careerById(s.career);return card('求学与工作',`<dl>${row('最高学历',educationNames[s.education])}${row('专业方向',s.major)}${row('社团',s.clubs.join('、')||'未加入')}${row('职业资格',s.qualifications.map(id=>careerById(id)?.name??'相关职业').join('、')||'暂无')}${row('当前职业',job(s))}${c?row('职业等级',c.levels[s.careerLevel])+row('基本年薪',money(s.salary))+row('工作投入',labels[s.effort])+row('行业经历',s.careerYears+'年'):''}${row('副业',s.sideJob?s.sideJob.name+' · 年收入'+money(s.sideJob.income):'暂无')}</dl>${c?`<h3 class="section-title">职业发展</h3><p class="footnote">${c.levels.join(' → ')}</p>`:''}<p class="footnote">工作、转行和迁居机会会随学历、能力、城市和经历出现。</p><h3 class="section-title">工作履历</h3><dl>${s.careerHistory.map(h=>row(careerById(h.career).name,`${h.startAge}～${h.endAge??s.age}岁 · ${cityById(h.city).name}`)).join('')||'<p class="footnote">第一份工作还在未来。</p>'}</dl>`);}
function wealthPage(s){return card('财富与安居',`<dl>${row('现金',money(s.cash))}${row('总资产（净值）',money(netWorth(s)))}${row('累计收入',money(s.totals.income))}${row('财富峰值',money(s.totals.peak))}${row('企业资产',money(s.company))}${row('创业方向',s.businessType??'尚未创业')}${row('负债（含房贷）',money(totalDebt(s)))}${row('信用',number(s.hidden.credit))}${row('当前住房',home(s)?'自有住房':s.age<18?'与父母同住':'租房')}</dl><h3 class="section-title">投资</h3><dl>${Object.entries(s.investments).map(([k,v])=>row(labels[k],money(v))).join('')}</dl><div class="list-actions">${Object.entries(s.investments).filter(([k,v])=>v>0&&k!=='venture').map(([k])=>button('取出'+labels[k],'withdraw','',!!s.pending,`data-key="${k}"`)).join('')}${s.debt>0?button('偿还其他债务','debt','',!!s.pending):''}</div><h3 class="section-title">房产</h3>${s.properties.length?s.properties.map(p=>`<section class="history-item"><h3>${cityById(p.city).name}的房子</h3><dl>${row('现值',money(p.value))}${row('剩余房贷',money(p.loan))}${row('状态',p.rented?'出租中':p.city===s.city?'自住':'保留空置')}</dl><div class="list-actions">${button('卖房','sell','',!!s.pending,`data-id="${p.id}"`)}${button(p.rented?'收回自住':'出租','rent','',!!s.pending,`data-id="${p.id}"`)}${button('提前还贷','repay','',!!s.pending||p.loan<=0||s.cash<=0,`data-id="${p.id}"`)}</div></section>`).join(''):'<p class="footnote">尚无房产。符合资金与信用条件时，会出现购房事件。</p>'}<p class="footnote">所有价格、收入和市场周期都是游戏参数，不对应真实行情。迁居后原房产继续保留。</p>`);}
function citiesPage(s){const c=cityById(s.city);return card('城市足迹',`<p>${esc(c.description)}</p><dl>${row('当前城市',c.name)}${row('熟悉度',s.familiarity+(s.adaptation?' · 适应期':' · 已安顿'))}${row('工资指数',c.wage)}${row('基础年生活成本',money(c.cost))}${row('参考房价',money(c.house))}${row('参考年租金',money(c.rent))}${row('家乡',cityById(s.birthCity).name)}</dl><div class="timeline">${s.cityHistory.map(h=>`<section><h3>${cityById(h.city).name}</h3><p>${h.startAge}～${h.endAge??s.age}岁 · ${esc(h.reason)}</p></section>`).join('')}</div>`);}
function historyPage(s){return card('人生履历',s.history.slice().reverse().map(h=>`<article class="history-item"><div class="meta">${h.year}年 · ${h.age}岁 · ${cityById(h.city).name}</div><h3>${esc(h.title)}</h3><p>${esc(h.text)}</p>${h.choice?`<p class="choice-taken">你的选择：${esc(h.choice)}</p>`:''}${h.background?.map(n=>`<p class="muted">${esc(n)}</p>`).join('')??''}</article>`).join(''));}
const renderers={year:yearPage,person:personPage,hobbies:hobbiesPage,relations:relationsPage,family:familyPage,career:careerPage,wealth:wealthPage,cities:citiesPage,history:historyPage};
function playPage(s){return `<div class="layout"><nav class="nav" aria-label="人生资料"><div class="nav-label">翻阅人生</div>${tabs.map(([id,text])=>button(text,'tab',tab===id?'active':'',false,`data-tab="${id}" ${tab===id?'aria-current="page"':''}`)).join('')}</nav><main class="main"><section class="person-header"><div><h1>${esc(s.name)}</h1><div class="status">${cityById(s.city).name} · ${esc(job(s))}</div></div><div class="age">${s.age}<span>岁</span></div></section>${tab==='year'?stats(s):''}${renderers[tab](s)}<div class="save-state" role="status">${saved?'已保存到此浏览器':'当前进度尚未保存'}</div></main><aside class="aside"><section><h3>此时此地</h3><p>${esc(cityById(s.city).description)}</p></section><section><h3>心之所向</h3><p>${esc(s.aspiration)}</p>${Object.entries(s.hobbies).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([k])=>`<span class="pill">${k}</span>`).join('')}</section><section><h3>留下的痕迹</h3><p>${s.tags.slice(-5).map(esc).join('、')||'故事才刚刚开始。'}</p></section></aside></div>`;}
function reportPage(s){const r=getReport(s);return `<main class="full"><header class="report-head"><div class="eyebrow">${s.birthYear} — ${s.birthYear+s.age}</div><h1>${esc(s.name)}的人生手记</h1><p>${r.title.map(esc).join(' · ')}</p><p class="muted">从${cityById(s.birthCity).name}出发，在${cityById(s.city).name}留下最后一页。</p></header><div class="page-card"><h2 class="section-title">各有所得，各有所憾</h2><div class="dimensions">${r.dimensions.map(([k,v])=>`<div class="dimension"><small>${k}</small>${esc(v)}</div>`).join('')}</div></div>${r.sections.map(section=>card(section.title,`<dl>${section.rows.map(([k,v])=>row(k,v)).join('')}</dl>`)).join('')}<div class="home-actions">${button('开始新人生','create','primary')}${button('历史人生','past')}${button('完整履历','report-history')}</div>${s.id===save.current?.id&&!s.rewindUsed&&save.checkpoint?button('使用最后一次时光倒流','rewind','quiet'):''}</main>`;}
function pastPage(){return `<main class="full">${card('历史人生',save.past.length?save.past.map((s,i)=>`<article class="history-item"><h3>${esc(s.name)} · ${s.age}岁</h3><p class="muted">${s.birthYear}～${s.birthYear+s.age}年 · ${titles(s).map(esc).join('、')}</p>${button('翻阅人生报告','archive','','',`data-index="${i}"`)}</article>`).join(''):'<p class="empty">走完第一段人生后，会在这里留下记录。</p>')}</main>`;}
function cancelAutoAdvance(){if(autoAdvanceTimer!==null){clearTimeout(autoAdvanceTimer);autoAdvanceTimer=null;}}
function isCurrentSlideActive(feed,current){return Math.abs(feed.scrollTop-current.offsetTop)<=Math.max(28,feed.clientHeight*.18);}
function scheduleAutoAdvance(s=save.current){cancelAutoAdvance();if(view!=='play'||tab!=='year'||busy||error||!saved||!s||s.pending||s.dead)return;const feed=root.querySelector('.year-feed'),current=feed?.querySelector('.year-slide.current');if(!feed||!current||!isCurrentSlideActive(feed,current))return;const id=s.id,age=s.age;autoAdvanceTimer=setTimeout(()=>{autoAdvanceTimer=null;const live=save.current;if(view!=='play'||tab!=='year'||busy||error||!saved||!live||live.id!==id||live.age!==age||live.pending||live.dead)return;const liveFeed=root.querySelector('.year-feed'),liveCurrent=liveFeed?.querySelector('.year-slide.current');if(!liveFeed||!liveCurrent||!isCurrentSlideActive(liveFeed,liveCurrent))return;act(async()=>{let next=advanceYear(save.current),cp=save.checkpoint;yearTransitionFromAge=age;if(next.pending&&!next.rewindUsed)cp=structuredClone(next);await persist(next,cp);if(next.dead){archive=null;view='report';}});},AUTO_ADVANCE_DELAY);}
function prepareYearFeed(s){cancelAutoAdvance();clearTimeout(yearFeedScrollTimer);const feed=root.querySelector('.year-feed'),current=feed?.querySelector('.year-slide.current');if(!feed||!current)return;const fromAge=yearTransitionFromAge;yearTransitionFromAge=null;const settle=()=>{clearTimeout(yearFeedScrollTimer);yearFeedScrollTimer=setTimeout(()=>scheduleAutoAdvance(save.current),220);};feed.addEventListener('scroll',()=>{cancelAutoAdvance();settle();},{passive:true});requestAnimationFrame(()=>{if(fromAge!==null){const previous=feed.querySelector(`.year-slide[data-age="${fromAge}"]`);if(previous)feed.scrollTop=previous.offsetTop;requestAnimationFrame(()=>{const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;current.scrollIntoView({block:'start',behavior:reduced?'auto':'smooth'});settle();});}else{feed.scrollTop=current.offsetTop;settle();}});}
function render(){document.documentElement.classList.toggle('large',prefs.largeText);let content=view==='home'?homePage():view==='create'?createPage():view==='past'?pastPage():view==='settings'?`<main class="full">${card('设置',`<label><input type="checkbox" id="large-text" ${prefs.largeText?'checked':''}> 使用较大文字</label><p class="footnote">无需登录。存档保存在当前浏览器，清理浏览器数据会同时清除存档。</p>`)}</main>`:view==='report'?reportPage(archive??save.current):view==='report-history'?`<main class="full">${button('返回人生报告','back-report')}${historyPage(archive??save.current)}</main>`:save.current?playPage(save.current):homePage();root.innerHTML=`<div class="shell">${header()}${error?`<div class="notice" role="alert">${esc(error)} ${button('重试保存','retry','',!ready)}</div>`:''}${content}<footer class="footer">这一生没有唯一的满分答案。</footer></div>`;if(view==='play'&&tab==='year'&&save.current&&!save.current.dead)prepareYearFeed(save.current);else cancelAutoAdvance();}
async function persist(current,checkpoint=save.checkpoint){save=updateSave(save,current,checkpoint);saved=false;await saveGame(save);saved=true;}
async function act(fn){if(busy)return;busy=true;error='';render();try{await fn();}catch(e){error=/[\u4e00-\u9fff]/.test(e.message)?e.message:'操作未完成，请重试。当前进度仍保留。';}finally{busy=false;render();}}
root.addEventListener('submit',e=>{if(e.target.id!=='create-form')return;e.preventDefault();const values=new FormData(e.target);act(async()=>{const s=createPlayer({seed:values.get('seed')||generateSeed(),name:values.get('name')||'',gender:values.get('gender'),city:values.get('city'),debug});await persist(s,null);archive=null;view='play';tab='year';});});
root.addEventListener('change',e=>{if(e.target.id==='city'){document.querySelector('#city-note').textContent=e.target.value==='random'?'出生地只是起点，你可以在重大人生节点迁居。':cityById(e.target.value).description;}if(e.target.id==='large-text'){prefs.largeText=e.target.checked;try{setSettings(prefs);}catch(err){error=err.message;}render();}});
root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;
 if(['home','create','past','settings'].includes(a)){view=a;archive=null;render();return;}
 if(a==='tab'){tab=b.dataset.tab;render();return;}
 if(a==='continue'){archive=null;view=save.current.dead?'report':'play';render();return;}
 if(a==='archive'){archive=save.past[Number(b.dataset.index)];view='report';render();return;}
 if(a==='report-history'){view='report-history';render();return;}
 if(a==='back-report'){view='report';render();return;}
 act(async()=>{
  if(a==='retry'){await saveGame(save);saved=true;return;}
  if(a==='debug'){const blob=new Blob([JSON.stringify({seed:save.current.seed,logs:save.current.debugLogs,audit:save.current.audit},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='人生调试日志.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  let s=save.current,cp=save.checkpoint;
  if(a==='choose'){s=choose(s,Number(b.dataset.index));}
  else if(a==='rewind'){s=rewind(s,cp);archive=null;view='play';tab='year';}
  else if(s.pending)throw Error('请先完成当前关键选择');
  else if(['sell','rent','repay'].includes(a)){s=applyEffects(s,[{type:'property',action:a,id:b.dataset.id}],'财富管理');}
  else if(a==='withdraw'){s=applyEffects(s,[{type:'invest',key:b.dataset.key,action:'withdraw',amount:s.investments[b.dataset.key]}],'取出投资');}
  else if(a==='debt')s=applyEffects(s,[{type:'settleDebt'}],'偿还债务');
  await persist(s,cp);if(s.dead){archive=null;view='report';}
 });
});
try{save=await loadSave();ready=true;}catch(e){error=e.message;}render();
